import{f as e,o as s,c as n,a2 as o}from"./chunks/framework.BUDOXiIz.js";const m=JSON.parse('{"title":"CoopApps — El modelo de datos","description":"","frontmatter":{},"headers":[],"relativePath":"presentacion-stakeholders/modelo-de-datos-para-imagenes.md","filePath":"presentacion-stakeholders/modelo-de-datos-para-imagenes.md","lastUpdated":null}'),t={name:"presentacion-stakeholders/modelo-de-datos-para-imagenes.md"};function i(r,a,l,d,c,p){return s(),n("div",null,[...a[0]||(a[0]=[o(`<h1 id="coopapps-—-el-modelo-de-datos" tabindex="-1">CoopApps — El modelo de datos <a class="header-anchor" href="#coopapps-—-el-modelo-de-datos" aria-label="Permalink to &quot;CoopApps — El modelo de datos&quot;">​</a></h1><p>Tres imágenes dedicadas al modelo de datos: qué tamaño tiene y cómo está organizado, cómo se garantiza que los datos no queden rotos ni huérfanos, y qué le pasa a un dato desde que nace hasta que la cooperativa se lo lleva. Todos los datos salen de la especificación; ninguno promete algo que no esté escrito.</p><table tabindex="0"><thead><tr><th>Dato</th><th>Valor</th></tr></thead><tbody><tr><td>Fecha</td><td>19-11-2026</td></tr><tr><td>Fuentes</td><td>T05 (§1, §6, §7.0–§7.10), <a href="./../especificacion/07-catalogo-tablas-sql"><code>07-catalogo-tablas-sql.md</code></a>, <a href="./../especificacion/07-ddl/README"><code>07-ddl/README.md</code></a> (<code>deploy-coopapps-full.sql</code>), <code>01</code> (DEC-110, DEC-117, DEC-064, DEC-075, DEC-097, DEC-100), T08 (RNF-NFR-260), <code>18-contratos-api.md</code> (1.069 esquemas API)</td></tr><tr><td>Relación con otros documentos</td><td><code>landing-stack-y-modelo-de-datos-para-imagenes.md</code> ya tiene seis imágenes del modelo (IMG-T11 a IMG-T16: tablas por ola, de la persona a la factura, de la factura al cobro, seis dominios, reglas comunes y crecimiento). Estas tres no las repiten: las completan</td></tr><tr><td>Datos</td><td>Todos los nombres de ejemplo son ficticios</td></tr></tbody></table><hr><h2 id="_0-como-usar-este-documento" tabindex="-1">0. Cómo usar este documento <a class="header-anchor" href="#_0-como-usar-este-documento" aria-label="Permalink to &quot;0. Cómo usar este documento&quot;">​</a></h2><ol><li>Si la conversación es nueva, pegar primero el prompt de la sección 0.1.</li><li>Pedir las imágenes por código: &quot;Generá IMG-MD01&quot;, &quot;Generá IMG-MD02&quot; y &quot;Generá IMG-MD03&quot;.</li><li>Cada imagen trae una <strong>frase para decir</strong> en voz alta mientras se muestra.</li></ol><h3 id="_0-1-prompt-de-estilo-pegar-primero" tabindex="-1">0.1 Prompt de estilo (pegar primero) <a class="header-anchor" href="#_0-1-prompt-de-estilo-pegar-primero" aria-label="Permalink to &quot;0.1 Prompt de estilo (pegar primero)&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Vas a dibujar tres diapositivas sobre el modelo de datos de un sistema para cooperativas de servicios públicos de Argentina. El público mezcla directivos y técnicos: cada imagen tiene que entenderse sin saber de bases de datos, y a la vez no decir nada que un técnico pueda objetar.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>El tono es seguro y sereno: el de alguien que ya hizo el trabajo y lo muestra. Nada de adjetivos vacíos (&quot;revolucionario&quot;, &quot;increíble&quot;, &quot;robusto&quot;, &quot;de última generación&quot;), nada de signos de exclamación, nada de lenguaje publicitario.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Reglas obligatorias:</span></span>
<span class="line"><span>1. Usá SOLO los textos y números del documento. No inventes cifras ni nombres de tablas o campos. Podés acortar sin cambiar el sentido.</span></span>
<span class="line"><span>2. Texto visible en español de Argentina. Nada de nombres de campos ni código en la imagen, salvo que el prompt lo pida.</span></span>
<span class="line"><span>3. Generá cada imagen con código (HTML con SVG en Claude; Python con matplotlib en ChatGPT), 1920×1080 px. No uses el generador de imágenes para nada que tenga texto.</span></span>
<span class="line"><span>4. Paleta: gris carbón #2F343A, gris medio #6B7280, gris claro #E5E7EB, blanco #FFFFFF y verde cooperativo #2E7D32 como único acento. Ámbar #B7791F solo donde el documento lo indique. Sin rojo.</span></span>
<span class="line"><span>5. Composición limpia: mucho espacio en blanco, un título grande (64 a 80 px), un elemento dominante y como máximo cinco elementos de apoyo. Texto mínimo de 20 px.</span></span>
<span class="line"><span>6. Tipografía sans serif limpia (Inter o similar), con peso fuerte en títulos y cifras.</span></span>
<span class="line"><span>7. Íconos de línea simples. Nada de cilindros 3D, nubes brillantes, robots ni efectos futuristas.</span></span>
<span class="line"><span>8. Después de cada imagen, listá qué datos del documento usaste.</span></span>
<span class="line"><span>Esperá mi pedido por código (IMG-MD01 a IMG-MD03).</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><hr><h2 id="_1-las-tres-ideas" tabindex="-1">1. Las tres ideas <a class="header-anchor" href="#_1-las-tres-ideas" aria-label="Permalink to &quot;1. Las tres ideas&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Código</th><th>Título de la imagen</th><th>Idea que deja</th></tr></thead><tbody><tr><td>IMG-MD01</td><td>1.058 tablas. Cada una con un solo dueño.</td><td>El modelo está completo y ordenado: nadie escribe lo que no le pertenece</td></tr><tr><td>IMG-MD02</td><td>Sin datos huérfanos.</td><td>Cinco mecanismos garantizan que las referencias entre datos no se rompan</td></tr><tr><td>IMG-MD03</td><td>La vida de un dato.</td><td>Cómo nace, cambia, se congela, se conserva y se entrega un dato</td></tr></tbody></table><hr><h2 id="_2-fichas-y-prompts" tabindex="-1">2. Fichas y prompts <a class="header-anchor" href="#_2-fichas-y-prompts" aria-label="Permalink to &quot;2. Fichas y prompts&quot;">​</a></h2><h3 id="img-md01-—-1-058-tablas-cada-una-con-un-solo-dueno" tabindex="-1">IMG-MD01 — 1.058 tablas. Cada una con un solo dueño. <a class="header-anchor" href="#img-md01-—-1-058-tablas-cada-una-con-un-solo-dueno" aria-label="Permalink to &quot;IMG-MD01 — 1.058 tablas. Cada una con un solo dueño.&quot;">​</a></h3><p><strong>Respaldo (T05 §1, §7.3–§7.10; DEC-117; <code>07-ddl</code>):</strong></p><ul><li>El modelo tiene <strong>1.058 tablas</strong> en <strong>Azure SQL</strong> (29 esquemas por módulo) y <strong>1.069 esquemas</strong> en los contratos de API.</li><li>Cada tabla tiene <strong>un único módulo dueño</strong>, sus claves, sus índices, su clasificación de datos y la ola en que se crea. <strong>Solo el dueño escribe su tabla</strong>: los demás módulos le piden los datos a su servicio o reciben sus eventos.</li><li>Se ordenan en seis dominios: plataforma e identidad; núcleo comercial; medición, tarifa y facturación; cuenta corriente, cobranza y mora; atención, técnica y stock; y ERP administrativo.</li><li>Una sola base compartida por todas las cooperativas, con la cooperativa en cada dato (<strong>DEC-110</strong>). La persona existe una sola vez aunque cumpla varios roles (DEC-097), y todo documento económico lleva la entidad jurídica que lo emite (DEC-064).</li><li>El detalle campo por campo vive en el anexo dueño; T05 es el catálogo lógico; el DDL ejecutable vive en <code>07-ddl</code>.</li></ul><p><strong>Frase para decir:</strong> &quot;El modelo no está esbozado: está completo. Más de mil tablas, y cada una tiene un solo dueño que responde por ella.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-MD01 con código.</span></span>
<span class="line"><span>Título grande: &quot;1.058 tablas. Cada una con un solo dueño.&quot;</span></span>
<span class="line"><span>Composición: en el centro, el número &quot;1.058&quot; enorme en verde con el rótulo &quot;tablas&quot;. Alrededor, seis bloques en anillo, cada uno con ícono de línea y su nombre:</span></span>
<span class="line"><span>&quot;Plataforma e identidad&quot; · &quot;Núcleo comercial&quot; · &quot;Medición, tarifa y facturación&quot; · &quot;Cuenta corriente, cobranza y mora&quot; · &quot;Atención, técnica y stock&quot; · &quot;ERP administrativo&quot;.</span></span>
<span class="line"><span>Dentro de cada bloque, una pequeña insignia gris con forma de llave: &quot;un dueño por tabla&quot;.</span></span>
<span class="line"><span>Debajo, una fila de tres afirmaciones con tilde verde: &quot;Solo el dueño escribe; los demás piden o escuchan&quot; · &quot;La persona existe una sola vez&quot; · &quot;Cada dato lleva su cooperativa&quot;.</span></span>
<span class="line"><span>Pie: &quot;Azure SQL · Esquema por módulo · Claves, índices, clasificación y ola de construcción&quot;.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h3 id="img-md02-—-sin-datos-huerfanos" tabindex="-1">IMG-MD02 — Sin datos huérfanos. <a class="header-anchor" href="#img-md02-—-sin-datos-huerfanos" aria-label="Permalink to &quot;IMG-MD02 — Sin datos huérfanos.&quot;">​</a></h3><p><strong>Respaldo (T05 §7.1.16, DEC-100, DEC-117; <code>07-ddl</code>):</strong> en <strong>Azure SQL</strong>, la integridad se combina con <strong>claves foráneas, índices únicos y constraints</strong> en el DDL desplegable (~1.900 referencias declaradas; ciclos documentados con control en despliegue inicial), más <strong>cinco mecanismos de aplicación</strong> que se suman:</p><ol><li><strong>Módulo dueño:</strong> antes de guardar una referencia a un dato de otro módulo, se confirma que existe, pertenece a la misma cooperativa y su estado lo permite. Un dato usado por un documento emitido no se borra: se desactiva.</li><li><strong>Foto de lo emitido:</strong> una factura guarda los datos tal como eran al emitirse; aunque algo cambie después, se reimprime igual.</li><li><strong>Validación en la base:</strong> reglas y FK en tablas económicas exigen referencias obligatorias, aunque alguien escriba sin pasar por el sistema.</li><li><strong>Control de versión:</strong> dos personas que modifican el mismo dato a la vez no se pisan; una baja que compite con un alta falla con aviso en lugar de dejar un huérfano.</li><li><strong>Verificador nocturno:</strong> cada noche, por cooperativa, recorre todas las referencias declaradas e <strong>informa</strong> cada una que esté rota, sin corregirla, a una bandeja con alerta a operaciones. Si un programador agrega una referencia sin declararla, la construcción del sistema falla.</li></ol><p>En la migración, además, se informan los huérfanos del sistema actual antes de cargar y se valida la integridad después de la carga.</p><p><strong>Frase para decir:</strong> &quot;Un dato nunca queda apuntando a la nada. Y si algo raro pasa, el sistema lo avisa a la mañana siguiente; no lo esconde ni lo arregla a ciegas.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-MD02 con código.</span></span>
<span class="line"><span>Título grande: &quot;Sin datos huérfanos.&quot;</span></span>
<span class="line"><span>Subtítulo: &quot;Cinco controles que se suman. Ninguno corrige a ciegas.&quot;</span></span>
<span class="line"><span>Composición: cinco capas horizontales apiladas, como un filtro, de arriba hacia abajo, cada una con su número, ícono de línea, nombre en negrita y una frase corta:</span></span>
<span class="line"><span>1. &quot;Módulo dueño&quot; — &quot;Antes de vincular, se confirma que el dato existe y es de la misma cooperativa&quot;</span></span>
<span class="line"><span>2. &quot;Foto de lo emitido&quot; — &quot;Una factura se reimprime igual aunque algo cambie después&quot;</span></span>
<span class="line"><span>3. &quot;Validación en la base&quot; — &quot;Las referencias obligatorias se exigen aunque se escriba por fuera&quot;</span></span>
<span class="line"><span>4. &quot;Control de versión&quot; — &quot;Dos cambios simultáneos no se pisan&quot;</span></span>
<span class="line"><span>5. &quot;Verificador nocturno&quot; — &quot;Cada noche informa cualquier referencia rota, sin corregirla&quot;</span></span>
<span class="line"><span>Las capas 1 a 4 en gris claro con borde gris; la capa 5 con borde verde y un ícono de luna pequeño.</span></span>
<span class="line"><span>A la derecha, una bandeja con un aviso ficticio: &quot;Referencia rota · Cooperativa A · 1 hallazgo · alerta a operaciones&quot;.</span></span>
<span class="line"><span>Pie: &quot;Una referencia nueva sin declarar hace fallar la construcción del sistema&quot;.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><h3 id="img-md03-—-la-vida-de-un-dato" tabindex="-1">IMG-MD03 — La vida de un dato. <a class="header-anchor" href="#img-md03-—-la-vida-de-un-dato" aria-label="Permalink to &quot;IMG-MD03 — La vida de un dato.&quot;">​</a></h3><p><strong>Respaldo (T05 §6, §7.1, §7.8.2; T08; T01):</strong></p><ol><li><strong>Nace</strong> con su cooperativa, su entidad jurídica si es económico, su autor y su fecha. Si tiene datos personales, nace clasificado; los sensibles (salud, judiciales, sindicales) y los bancarios se cifran. Ninguna contraseña ni certificado se guarda junto a los datos: van a una bóveda.</li><li><strong>Cambia</strong> con control de versión: cada cambio registra quién, cuándo y qué, y dos personas no se pisan.</li><li><strong>Se congela al emitirse:</strong> un comprobante guarda la foto de sus datos; no se borra ni se edita, se corrige con un documento contrario.</li><li><strong>Se conserva:</strong> facturas, recibos, asientos y movimientos quedan en línea los 10 años. El detalle accesorio de más de 36 meses se archiva cifrado por cooperativa, y el saldo de una cuenta nunca depende del archivo.</li><li><strong>Se entrega:</strong> la cooperativa puede exportar sus datos cuando quiera; si deja el servicio, recibe la exportación completa en formatos abiertos, con control de integridad.</li></ol><p>Lo que llega del sistema actual conserva la referencia a su registro de origen, para verificar cada dato migrado.</p><p><strong>Frase para decir:</strong> &quot;Cada dato sabe de quién es, quién lo tocó y qué valía cuando se emitió. Y el día que la cooperativa lo pida, se lo lleva completo.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-MD03 con código.</span></span>
<span class="line"><span>Título grande: &quot;La vida de un dato.&quot;</span></span>
<span class="line"><span>Composición: una línea de tiempo horizontal con cinco etapas, cada una con un círculo numerado, ícono de línea, verbo grande y dos líneas de apoyo:</span></span>
<span class="line"><span>1. &quot;Nace&quot; — &quot;Con su cooperativa, su autor y su fecha&quot; · &quot;Datos sensibles cifrados; contraseñas en bóveda&quot;</span></span>
<span class="line"><span>2. &quot;Cambia&quot; — &quot;Quién, cuándo y qué&quot; · &quot;Dos personas no se pisan&quot;</span></span>
<span class="line"><span>3. &quot;Se congela&quot; — &quot;Lo emitido guarda su foto&quot; · &quot;Se corrige con un documento contrario&quot;</span></span>
<span class="line"><span>4. &quot;Se conserva&quot; — &quot;Comprobantes y asientos: 10 años en línea&quot; · &quot;Detalle accesorio: archivado y cifrado a los 36 meses&quot;</span></span>
<span class="line"><span>5. &quot;Se entrega&quot; — &quot;Exportación cuando la cooperativa quiera&quot; · &quot;Completa y en formatos abiertos si se va&quot;</span></span>
<span class="line"><span>Las etapas 1 a 4 en gris carbón; la etapa 5 en verde.</span></span>
<span class="line"><span>Debajo de la línea, una franja gris claro: &quot;Lo migrado conserva la referencia a su registro de origen&quot;.</span></span>
<span class="line"><span>Pie: &quot;El saldo de una cuenta nunca depende del archivo&quot;.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><hr><h2 id="_3-notas-para-el-presentador" tabindex="-1">3. Notas para el presentador <a class="header-anchor" href="#_3-notas-para-el-presentador" aria-label="Permalink to &quot;3. Notas para el presentador&quot;">​</a></h2><ul><li><strong>Cómo combinarlas con las del documento de landing y stack.</strong> Para un bloque completo de modelo de datos: IMG-MD01, IMG-T14 (seis dominios), IMG-T12 (de la persona a la factura), IMG-MD02, IMG-MD03 e IMG-T16 (pensado para crecer).</li><li><strong>Integridad relacional.</strong> La base es <strong>Azure SQL</strong> con PK/FK y los cinco mecanismos de IMG-MD02 (DEC-100, DEC-117). Detalle en <code>07-modelo-relacional-azure-sql.md</code>.</li><li><strong>No mostrar campos ni tipos.</strong> Si alguien técnico los pide, se abre <code>T05</code> o el §7 del anexo dueño; la imagen no se agranda.</li><li><strong>&quot;Una sola base compartida&quot;</strong> puede inquietar a un directivo. La respuesta está en IMG-T06 (&quot;Una base, muchas cooperativas, ningún cruce.&quot;): el aislamiento está en cada capa y se prueba.</li></ul>`,33)])])}const b=e(t,[["render",i]]);export{m as __pageData,b as default};
